45	                    && soundex.equals(Soundex.encode(existing.getLastName()))
46	                    && !identityKey.equals(existing.getIdentityKey())) {
47	                owner.setPossibleDuplicate(true);
48	                owner.setPossibleDuplicateOf(existing.getId());
49	                return;
50	            }
51	        }
52	    }
